import { logOpsReceipt, getReceipts } from '../../../src/lib/ops-gate';
import { enforceReplayCheck } from '../../../src/lib/manager-receipts';
import * as path from 'path';
import * as fs from 'fs';

const TEST_DIR = path.resolve(process.cwd(), '.state/test-ops');

// Ensure clean state
if (fs.existsSync(TEST_DIR)) {
  fs.rmSync(TEST_DIR, { recursive: true, force: true });
}
fs.mkdirSync(TEST_DIR, { recursive: true });

async function run() {
  console.log("Starting Ops Gate Smoke Test...");

  // 1. Test Ops Receipt Logging
  const receipt = {
    id: "test-id-" + Date.now(),
    agent: "test-agent",
    tool: "write",
    args: { path: "test.txt" },
    timestamp: Date.now()
  };

  console.log("Logging receipt...");
  logOpsReceipt(receipt, TEST_DIR);

  const receipts = getReceipts(TEST_DIR);
  if (receipts.length !== 1 || receipts[0].id !== receipt.id) {
    console.error("❌ FAILED: Receipt not found or mismatch");
    process.exit(1);
  }
  console.log("✅ Ops Receipt logged and read back.");

  // 2. Test Experience Replay Enforcer (Manager Receipts)
  console.log("Testing Replay Enforcer...");
  try {
    // This should NOT throw because we haven't logged an error for this tool/args
    enforceReplayCheck("test-agent", "write", { path: "unique-file.txt" }, TEST_DIR);
    console.log("✅ Enforcer allowed fresh action.");
  } catch (e) {
    console.error("❌ FAILED: Enforcer blocked fresh action", e);
    process.exit(1);
  }

  console.log("Smoke Test Complete.");
}

run().catch(e => {
  console.error("❌ CRITICAL FAILURE:", e);
  process.exit(1);
});

